/**
 * LeoPay database schema (PostgreSQL).
 *
 * Conventions:
 * - Primary keys are UUIDs generated by the database (`gen_random_uuid()`).
 * - Monetary values are stored as integer minor units (kobo for NGN) in `bigint`.
 * - All timestamps are `timestamptz` and stored in UTC.
 * - Every business record carries `organization_id`, the tenant boundary.
 * - Financial state columns use enums so invalid states cannot be persisted.
 */
import {
  bigint,
  boolean,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/* ------------------------------------------------------------------ enums */

export const paymentStatusEnum = pgEnum("payment_status", [
  "created",
  "pending",
  "processing",
  "succeeded",
  "failed",
  "cancelled",
  "expired",
  "refunded",
  "partially_refunded",
]);

export const payoutStatusEnum = pgEnum("payout_status", [
  "requested",
  "pending_approval",
  "approved",
  "processing",
  "succeeded",
  "failed",
  "reversed",
]);

export const invoiceStatusEnum = pgEnum("invoice_status", [
  "draft",
  "issued",
  "partially_paid",
  "paid",
  "overdue",
  "cancelled",
]);

export const orderStatusEnum = pgEnum("order_status", [
  "pending_payment",
  "paid",
  "fulfilled",
  "cancelled",
  "refunded",
]);

/* ------------------------------------------------------- identity & tenancy */

export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email").notNull(),
    emailVerifiedAt: timestamp("email_verified_at", { withTimezone: true }),
    name: text("name").notNull(),
    passwordHash: text("password_hash"),
    avatarUrl: text("avatar_url"),
    status: text("status").notNull().default("active"), // active | suspended
    platformRole: text("platform_role").notNull().default("user"), // user | admin
    mfaEnabled: boolean("mfa_enabled").notNull().default(false),
    lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_email_unique").on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull().unique(),
    csrfToken: text("csrf_token").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    ip: text("ip"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

export const verificationTokens = pgTable(
  "verification_tokens",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").notNull(), // email_verify | password_reset
    tokenHash: text("token_hash").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("verification_tokens_user_idx").on(t.userId, t.type)],
);

export const organizations = pgTable(
  "organizations",
  {
    id: id(),
    name: text("name").notNull(),
    slug: text("slug").notNull().unique(),
    businessEmail: text("business_email"),
    businessPhone: text("business_phone"),
    countryCode: text("country_code").notNull().default("NG"),
    defaultCurrency: text("default_currency").notNull().default("NGN"),
    businessType: text("business_type"), // sole_proprietorship | limited_company | freelancer | ngo | other
    website: text("website"),
    settlementBankName: text("settlement_bank_name"),
    settlementAccountName: text("settlement_account_name"),
    settlementAccountNumberLast4: text("settlement_account_number_last4"),
    verificationStatus: text("verification_status").notNull().default("unverified"), // unverified | pending | verified | rejected
    status: text("status").notNull().default("active"), // active | suspended
    onboardingStep: text("onboarding_step").notNull().default("business_details"),
    onboardingCompletedAt: timestamp("onboarding_completed_at", { withTimezone: true }),
    /** Payouts at or above this amount require a second approver. */
    payoutApprovalThresholdMinor: bigint("payout_approval_threshold_minor", { mode: "number" }).notNull().default(10_000_000),
    /** Rolling 24h payout ceiling for the organization. */
    payoutDailyLimitMinor: bigint("payout_daily_limit_minor", { mode: "number" }).notNull().default(50_000_000),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("organizations_slug_idx").on(t.slug)],
);

export const memberships = pgTable(
  "memberships",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: text("role").notNull().default("viewer"), // owner | admin | finance | developer | viewer
    status: text("status").notNull().default("active"), // active | suspended
    invitedAt: timestamp("invited_at", { withTimezone: true }),
    joinedAt: timestamp("joined_at", { withTimezone: true }).defaultNow(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("memberships_org_user_unique").on(t.organizationId, t.userId),
    index("memberships_user_idx").on(t.userId),
  ],
);

export const invitations = pgTable(
  "invitations",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    email: text("email").notNull(),
    role: text("role").notNull().default("viewer"),
    tokenHash: text("token_hash").notNull().unique(),
    invitedBy: uuid("invited_by").references(() => users.id, { onDelete: "set null" }),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    acceptedAt: timestamp("accepted_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("invitations_org_idx").on(t.organizationId), index("invitations_email_idx").on(t.email)],
);

/* ------------------------------------------------------------- commercial */

export const customers = pgTable(
  "customers",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    email: text("email"),
    phone: text("phone"),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("customers_org_idx").on(t.organizationId, t.createdAt)],
);

export const paymentLinks = pgTable(
  "payment_links",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    publicReference: text("public_reference").notNull().unique(),
    title: text("title").notNull(),
    description: text("description"),
    amountMinor: bigint("amount_minor", { mode: "number" }),
    currency: text("currency").notNull().default("NGN"),
    status: text("status").notNull().default("active"), // active | disabled | expired
    allowVariableAmount: boolean("allow_variable_amount").notNull().default(false),
    minAmountMinor: bigint("min_amount_minor", { mode: "number" }),
    maxAmountMinor: bigint("max_amount_minor", { mode: "number" }),
    successUrl: text("success_url"),
    cancelUrl: text("cancel_url"),
    collectCustomerName: boolean("collect_customer_name").notNull().default(true),
    collectCustomerEmail: boolean("collect_customer_email").notNull().default(true),
    collectCustomerPhone: boolean("collect_customer_phone").notNull().default(false),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("payment_links_org_idx").on(t.organizationId, t.createdAt)],
);

export const payments = pgTable(
  "payments",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "restrict" }),
    customerId: uuid("customer_id").references(() => customers.id, { onDelete: "set null" }),
    paymentLinkId: uuid("payment_link_id").references(() => paymentLinks.id, { onDelete: "set null" }),
    invoiceId: uuid("invoice_id"),
    orderId: uuid("order_id"),
    internalReference: text("internal_reference").notNull().unique(),
    providerReference: text("provider_reference"),
    provider: text("provider").notNull(),
    amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
    feeMinor: bigint("fee_minor", { mode: "number" }),
    netMinor: bigint("net_minor", { mode: "number" }),
    currency: text("currency").notNull(),
    status: paymentStatusEnum("status").notNull().default("created"),
    paymentMethod: text("payment_method"),
    channel: text("channel"), // hosted_link | invoice | storefront | api
    failureCode: text("failure_code"),
    failureMessage: text("failure_message"),
    customerEmail: text("customer_email"),
    customerName: text("customer_name"),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().default({}),
    paidAt: timestamp("paid_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("payments_org_created_idx").on(t.organizationId, t.createdAt),
    index("payments_status_idx").on(t.organizationId, t.status),
    uniqueIndex("payments_provider_reference_unique")
      .on(t.provider, t.providerReference)
      .where(sql`${t.providerReference} is not null`),
  ],
);

export const refunds = pgTable(
  "refunds",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "restrict" }),
    paymentId: uuid("payment_id")
      .notNull()
      .references(() => payments.id, { onDelete: "restrict" }),
    amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
    currency: text("currency").notNull(),
    reason: text("reason"),
    status: text("status").notNull().default("pending"), // pending | succeeded | failed
    providerReference: text("provider_reference"),
    provider: text("provider").notNull(),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("refunds_payment_idx").on(t.paymentId)],
);

export const invoices = pgTable(
  "invoices",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    customerId: uuid("customer_id").references(() => customers.id, { onDelete: "set null" }),
    invoiceNumber: text("invoice_number").notNull(),
    publicReference: text("public_reference").notNull().unique(),
    currency: text("currency").notNull().default("NGN"),
    subtotalMinor: bigint("subtotal_minor", { mode: "number" }).notNull().default(0),
    discountMinor: bigint("discount_minor", { mode: "number" }).notNull().default(0),
    taxMinor: bigint("tax_minor", { mode: "number" }).notNull().default(0),
    totalMinor: bigint("total_minor", { mode: "number" }).notNull().default(0),
    amountPaidMinor: bigint("amount_paid_minor", { mode: "number" }).notNull().default(0),
    taxRateBps: integer("tax_rate_bps").notNull().default(0),
    status: invoiceStatusEnum("status").notNull().default("draft"),
    issueDate: timestamp("issue_date", { withTimezone: true }).notNull().defaultNow(),
    dueDate: timestamp("due_date", { withTimezone: true }),
    notes: text("notes"),
    terms: text("terms"),
    customerName: text("customer_name"),
    customerEmail: text("customer_email"),
    sentAt: timestamp("sent_at", { withTimezone: true }),
    lastReminderAt: timestamp("last_reminder_at", { withTimezone: true }),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("invoices_org_number_unique").on(t.organizationId, t.invoiceNumber),
    index("invoices_org_status_idx").on(t.organizationId, t.status),
  ],
);

export const invoiceItems = pgTable(
  "invoice_items",
  {
    id: id(),
    invoiceId: uuid("invoice_id")
      .notNull()
      .references(() => invoices.id, { onDelete: "cascade" }),
    description: text("description").notNull(),
    quantity: numeric("quantity", { precision: 14, scale: 3 }).notNull().default("1"),
    unitAmountMinor: bigint("unit_amount_minor", { mode: "number" }).notNull(),
    amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
    position: integer("position").notNull().default(0),
  },
  (t) => [index("invoice_items_invoice_idx").on(t.invoiceId)],
);

export const invoiceSequences = pgTable(
  "invoice_sequences",
  {
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    year: integer("year").notNull(),
    nextNumber: integer("next_number").notNull().default(1),
  },
  (t) => [uniqueIndex("invoice_sequences_pk").on(t.organizationId, t.year)],
);

export const storefronts = pgTable(
  "storefronts",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    description: text("description"),
    logoUrl: text("logo_url"),
    coverUrl: text("cover_url"),
    currency: text("currency").notNull().default("NGN"),
    status: text("status").notNull().default("draft"), // draft | published | unpublished
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("storefronts_org_unique").on(t.organizationId)],
);

export const products = pgTable(
  "products",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    storefrontId: uuid("storefront_id").references(() => storefronts.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    description: text("description"),
    priceMinor: bigint("price_minor", { mode: "number" }).notNull(),
    currency: text("currency").notNull().default("NGN"),
    sku: text("sku"),
    imageUrl: text("image_url"),
    trackInventory: boolean("track_inventory").notNull().default(false),
    inventoryQuantity: integer("inventory_quantity").notNull().default(0),
    status: text("status").notNull().default("draft"), // draft | active | archived
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("products_org_slug_unique").on(t.organizationId, t.slug),
    index("products_org_idx").on(t.organizationId, t.status),
  ],
);

export const orders = pgTable(
  "orders",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "restrict" }),
    storefrontId: uuid("storefront_id").references(() => storefronts.id, { onDelete: "set null" }),
    publicReference: text("public_reference").notNull().unique(),
    customerName: text("customer_name").notNull(),
    customerEmail: text("customer_email").notNull(),
    customerPhone: text("customer_phone"),
    deliveryNote: text("delivery_note"),
    currency: text("currency").notNull(),
    subtotalMinor: bigint("subtotal_minor", { mode: "number" }).notNull(),
    shippingMinor: bigint("shipping_minor", { mode: "number" }).notNull().default(0),
    totalMinor: bigint("total_minor", { mode: "number" }).notNull(),
    status: orderStatusEnum("status").notNull().default("pending_payment"),
    paymentId: uuid("payment_id").references(() => payments.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("orders_org_idx").on(t.organizationId, t.createdAt)],
);

export const orderItems = pgTable(
  "order_items",
  {
    id: id(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: uuid("product_id").references(() => products.id, { onDelete: "set null" }),
    nameSnapshot: text("name_snapshot").notNull(),
    unitAmountMinor: bigint("unit_amount_minor", { mode: "number" }).notNull(),
    quantity: integer("quantity").notNull(),
    amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
  },
  (t) => [index("order_items_order_idx").on(t.orderId)],
);

export const inventoryMovements = pgTable(
  "inventory_movements",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    delta: integer("delta").notNull(),
    reason: text("reason").notNull(), // order_reserved | order_released | manual_adjustment
    orderId: uuid("order_id").references(() => orders.id, { onDelete: "set null" }),
    actorId: uuid("actor_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("inventory_movements_product_idx").on(t.productId, t.createdAt)],
);

/* ---------------------------------------------------------------- payouts */

export const beneficiaries = pgTable(
  "beneficiaries",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    type: text("type").notNull().default("bank_account"),
    bankCode: text("bank_code").notNull(),
    bankName: text("bank_name").notNull(),
    accountNumberEncrypted: text("account_number_encrypted").notNull(),
    accountNumberLast4: text("account_number_last4").notNull(),
    accountName: text("account_name").notNull(),
    verificationStatus: text("verification_status").notNull().default("unverified"), // unverified | verified | failed
    providerRecipientReference: text("provider_recipient_reference"),
    status: text("status").notNull().default("active"),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("beneficiaries_org_idx").on(t.organizationId),
    uniqueIndex("beneficiaries_org_account_unique").on(t.organizationId, t.bankCode, t.accountNumberLast4, t.accountName),
  ],
);

export const payouts = pgTable(
  "payouts",
  {
    id: id(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "restrict" }),
    beneficiaryId: uuid("beneficiary_id")
      .notNull()
      .references(() => beneficiaries.id, { onDelete: "restrict" }),
    internalReference: text("internal_reference").notNull().unique(),
    providerReference: text("provider_reference"),
    provider: text("provider").notNull(),
    amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
    currency: text("currency").notNull(),
    status: payoutStatusEnum("status").notNull().default("requested"),
    reason: text("reason"),
    requestedBy: uuid("requested_by").references(() => users.id, { onDelete: "set null" }),
    approvedBy: uuid("approved_by").references(() => users.id, { onDelete: "set null" }),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    failureCode: text("failure_code"),
    failureMessage: text("failure_message"),
    idempotencyKey: text("idempotency_key"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("payouts_org_idx").on(t.organizationId, t.createdAt),
    uniqueIndex("payouts_org_idempotency_unique")
      .on(t.organizationId, t.idempotencyKey)
      .where(sql`${t.idempotencyKey} is not null`),
  ],
);

export const payoutEvents = pgTable(
  "payout_events",
  {
    id: id(),
    payoutId: uuid("payout_id")
      .notNull()
      .references(() => payouts.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    message: text("message"),
    actorId: uuid("actor_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("payout_events_payout_idx").on(t.payoutId)],
);

